module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButtonEmpty,\n  EuiContextMenuItem,\n  EuiContextMenuPanel,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiPagination,\n  EuiPopover,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n      activePage: 0,\n    };\n\n    this.PAGE_COUNT = 10;\n  }\n\n  onButtonClick() {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  }\n\n  closePopover() {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  }\n\n  goToPage = pageNumber => {\n    this.setState({\n      activePage: pageNumber,\n    });\n  };\n\n  render() {\n    const button = (\n      <EuiButtonEmpty\n        size=\"s\"\n        color=\"text\"\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick.bind(this)}>\n        Rows per page: 50\n      </EuiButtonEmpty>\n    );\n\n    const items = [\n      <EuiContextMenuItem\n        key=\"10 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('10 rows');\n        }}>\n        10 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"20 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('20 rows');\n        }}>\n        20 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"50 rows\"\n        icon=\"check\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('50 rows');\n        }}>\n        50 rows\n      </EuiContextMenuItem>,\n      <EuiContextMenuItem\n        key=\"100 rows\"\n        icon=\"empty\"\n        onClick={() => {\n          this.closePopover();\n          window.alert('100 rows');\n        }}>\n        100 rows\n      </EuiContextMenuItem>,\n    ];\n\n    return (\n      <EuiFlexGroup justifyContent=\"spaceBetween\" alignItems=\"center\">\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"customizablePagination\"\n            button={button}\n            isOpen={this.state.isPopoverOpen}\n            closePopover={this.closePopover.bind(this)}\n            panelPaddingSize=\"none\">\n            <EuiContextMenuPanel items={items} />\n          </EuiPopover>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiPagination\n            pageCount={this.PAGE_COUNT}\n            activePage={this.state.activePage}\n            onPageClick={this.goToPage}\n          />\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n  }\n}\n"