module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiFieldSearch, EuiSpacer } from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: '',\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiFieldSearch\n          placeholder=\"Placeholder text\"\n          value={this.state.value}\n          onChange={this.onChange}\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldSearch\n          placeholder=\"Disabled\"\n          value={this.state.value}\n          onChange={this.onChange}\n          disabled\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldSearch\n          placeholder=\"Loading\"\n          value={this.state.value}\n          onChange={this.onChange}\n          isLoading\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldSearch\n          placeholder=\"Loading and disabled\"\n          value={this.state.value}\n          onChange={this.onChange}\n          isLoading\n          disabled\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldSearch\n          placeholder=\"Read-only\"\n          value={this.state.value}\n          onChange={this.onChange}\n          readOnly\n          aria-label=\"Use aria labels when no actual label is in use\"\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiFieldSearch\n          placeholder=\"Compressed\"\n          value={this.state.value}\n          onChange={this.onChange}\n          compressed\n        />\n      </Fragment>\n    );\n  }\n}\n"