module.exports = "import React, { Component, Fragment } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiLink,\n  EuiHealth,\n  EuiButton,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiSwitch,\n  EuiSpacer,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n      selectedItems: [],\n      multiAction: false,\n      customAction: false,\n    };\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const { index: pageIndex, size: pageSize } = page;\n\n    const { field: sortField, direction: sortDirection } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  onClickDelete = () => {\n    const { selectedItems } = this.state;\n    store.deleteUsers(...selectedItems.map(user => user.id));\n\n    this.setState({\n      selectedItems: [],\n    });\n  };\n\n  onSelectionChange = selectedItems => {\n    this.setState({ selectedItems });\n  };\n\n  renderDeleteButton() {\n    const { selectedItems } = this.state;\n\n    if (selectedItems.length === 0) {\n      return;\n    }\n\n    return (\n      <EuiFlexItem grow={false}>\n        <EuiButton color=\"danger\" iconType=\"trash\" onClick={this.onClickDelete}>\n          Delete {selectedItems.length} Users\n        </EuiButton>\n      </EuiFlexItem>\n    );\n  }\n\n  toggleMultiAction = () => {\n    this.setState(prevState => ({ multiAction: !prevState.multiAction }));\n  };\n\n  toggleCustomAction = () => {\n    this.setState(prevState => ({ customAction: !prevState.customAction }));\n  };\n\n  deleteUser = user => {\n    store.deleteUsers(user.id);\n    this.setState({ selectedItems: [] });\n  };\n\n  cloneUser = user => {\n    store.cloneUser(user.id);\n    this.setState({ selectedItems: [] });\n  };\n\n  render() {\n    const {\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n      multiAction,\n      customAction,\n    } = this.state;\n\n    const { pageOfItems, totalItemCount } = store.findUsers(\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection\n    );\n\n    const deleteButton = this.renderDeleteButton();\n\n    let actions = null;\n\n    if (multiAction) {\n      actions = customAction\n        ? [\n            {\n              render: item => {\n                return (\n                  <EuiLink\n                    color=\"secondary\"\n                    onClick={() => this.cloneUser(item)}>\n                    Clone\n                  </EuiLink>\n                );\n              },\n            },\n            {\n              render: item => {\n                return (\n                  <EuiLink color=\"danger\" onClick={() => this.deleteUser(item)}>\n                    Delete\n                  </EuiLink>\n                );\n              },\n            },\n          ]\n        : [\n            {\n              name: 'Clone',\n              description: 'Clone this user',\n              icon: 'copy',\n              onClick: this.cloneUser,\n            },\n            {\n              name: 'Delete',\n              description: 'Delete this user',\n              icon: 'trash',\n              color: 'danger',\n              type: 'icon',\n              onClick: this.deleteUser,\n              isPrimary: true,\n            },\n            {\n              name: 'Edit',\n              isPrimary: true,\n              description: 'Edit this user',\n              icon: 'pencil',\n              type: 'icon',\n              onClick: () => {},\n            },\n            {\n              name: 'Share',\n              isPrimary: true,\n              description: 'Share this user',\n              icon: 'share',\n              type: 'icon',\n              onClick: () => {},\n            },\n          ];\n    } else {\n      actions = customAction\n        ? [\n            {\n              render: item => {\n                return (\n                  <EuiLink onClick={() => this.deleteUser(item)} color=\"danger\">\n                    Delete\n                  </EuiLink>\n                );\n              },\n            },\n          ]\n        : [\n            {\n              name: 'Elastic.co',\n              description: 'Go to elastic.co',\n              icon: 'editorLink',\n              color: 'primary',\n              type: 'icon',\n              href: 'https://elastic.co',\n              target: '_blank',\n            },\n          ];\n    }\n\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        truncateText: true,\n        sortable: true,\n        mobileOptions: {\n          render: item => (\n            <span>\n              {item.firstName} {item.lastName}\n            </span>\n          ),\n          header: false,\n          truncateText: false,\n          enlarge: true,\n          fullWidth: true,\n        },\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        truncateText: true,\n        mobileOptions: {\n          show: false,\n        },\n      },\n      {\n        field: 'github',\n        name: 'Github',\n        render: username => (\n          <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n            {username}\n          </EuiLink>\n        ),\n      },\n      {\n        field: 'dateOfBirth',\n        name: 'Date of Birth',\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n        sortable: true,\n      },\n      {\n        field: 'nationality',\n        name: 'Nationality',\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: 'Online',\n        dataType: 'boolean',\n        render: online => {\n          const color = online ? 'success' : 'danger';\n          const label = online ? 'Online' : 'Offline';\n          return <EuiHealth color={color}>{label}</EuiHealth>;\n        },\n        sortable: true,\n      },\n      {\n        name: 'Actions',\n        actions,\n      },\n    ];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8],\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    const selection = {\n      selectable: user => user.online,\n      selectableMessage: selectable =>\n        !selectable ? 'User is currently offline' : undefined,\n      onSelectionChange: this.onSelectionChange,\n    };\n\n    return (\n      <Fragment>\n        <EuiFlexGroup alignItems=\"center\">\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Multiple Actions\"\n              checked={this.state.multiAction}\n              onChange={this.toggleMultiAction}\n            />\n          </EuiFlexItem>\n          <EuiFlexItem grow={false}>\n            <EuiSwitch\n              label=\"Custom Actions\"\n              checked={this.state.customAction}\n              onChange={this.toggleCustomAction}\n            />\n          </EuiFlexItem>\n          <EuiFlexItem />\n          {deleteButton}\n        </EuiFlexGroup>\n\n        <EuiSpacer size=\"l\" />\n\n        <EuiBasicTable\n          items={pageOfItems}\n          itemId=\"id\"\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          selection={selection}\n          hasActions={customAction ? false : true}\n          onChange={this.onTableChange}\n        />\n      </Fragment>\n    );\n  }\n}\n"