module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiSpacer } from '../../../../src/components';\nimport {\n  EuiSeriesChart,\n  EuiHistogramSeries,\n  EuiSeriesChartUtils,\n} from '../../../../src/experimental';\nimport { colorPalette, palettes } from '../../../../src/services/color';\n\nconst { SCALE } = EuiSeriesChartUtils;\nconst timestamp = Date.now();\nconst ONE_HOUR = 3600000;\nconst margins = {\n  top: 10,\n  left: 80,\n  right: 0,\n  bottom: 20,\n};\nconst qualColors = palettes.euiPaletteColorBlind.colors;\nconst quantColors = colorPalette('#FFFF6D', '#1EA593', 6);\n\nfunction randomizeData(size = 24, max = 8) {\n  return new Array(size)\n    .fill(0)\n    .map((d, i) => ({\n      x0: ONE_HOUR * i,\n      x: ONE_HOUR * (i + 1),\n      y: Math.floor(Math.random() * max),\n    }))\n    .map(el => ({\n      x0: el.x0 + timestamp,\n      x: el.x + timestamp,\n      y: el.y,\n    }));\n}\nfunction buildData(series) {\n  const max = Math.ceil(Math.random() * 1000000);\n  return new Array(series).fill(0).map(() => randomizeData(20, max));\n}\nexport default class Example extends Component {\n  state = {\n    series: 6,\n    data: buildData(6),\n  };\n  render() {\n    const { data } = this.state;\n    return (\n      <Fragment>\n        <EuiSeriesChart\n          width={600}\n          height={200}\n          xType={SCALE.TIME}\n          stackBy=\"y\"\n          margins={margins}>\n          {data.map((d, i) => (\n            <EuiHistogramSeries\n              key={i}\n              name={`Chart ${i}`}\n              data={d}\n              color={qualColors[i]}\n            />\n          ))}\n        </EuiSeriesChart>\n        <EuiSpacer size=\"xl\" />\n        <EuiSeriesChart\n          width={600}\n          height={200}\n          xType={SCALE.TIME}\n          stackBy=\"y\"\n          margins={margins}>\n          {data.map((d, i) => (\n            <EuiHistogramSeries\n              key={i}\n              name={`Chart ${i}`}\n              data={d}\n              color={quantColors[i]}\n            />\n          ))}\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"