module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiSpacer, EuiButton } from '../../../../src/components';\n\nimport {\n  EuiSeriesChart,\n  EuiBarSeries,\n  EuiSeriesChartUtils,\n} from '../../../../src/experimental';\n\nconst { SCALE } = EuiSeriesChartUtils;\n\nconst dataA = [\n  { x: 0, y: 5 },\n  { x: 1, y: 4 },\n  { x: 2, y: 3 },\n  { x: 3, y: 2 },\n  { x: 4, y: 1 },\n];\n\nconst dataB = [\n  { x: 0, y: 1 },\n  { x: 1, y: 2 },\n  { x: 2, y: 3 },\n  { x: 3, y: 4 },\n  { x: 4, y: 5 },\n];\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      stacked: true,\n    };\n  }\n\n  onSwitchStacked = () => {\n    this.setState({\n      stacked: !this.state.stacked,\n    });\n  };\n\n  render() {\n    const { stacked } = this.state;\n    return (\n      <Fragment>\n        <EuiButton color=\"primary\" onClick={this.onSwitchStacked}>\n          Toggle stacked\n        </EuiButton>\n        <EuiSpacer size=\"l\" />\n        <EuiSeriesChart\n          width={600}\n          height={200}\n          xType={SCALE.ORDINAL}\n          stackBy={stacked ? 'y' : null}>\n          <EuiBarSeries name={'Tag A'} data={dataA} />\n          <EuiBarSeries name={'Tag B'} data={dataB} />\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"