module.exports = "import React, { useState } from 'react';\nimport {\n  EuiDragDropContext,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiDraggable,\n  EuiDroppable,\n  EuiPanel,\n} from '../../../../src/components';\n\nimport { move, reorder } from '../../../../src/components/drag_and_drop';\n\nimport { makeList } from './helper';\n\nexport default () => {\n  const [list1, setList1] = useState(makeList(3));\n  const [list2, setList2] = useState(makeList(3, 4));\n  const [list3, setList3] = useState(makeList(3, 7));\n  const onDragEnd = ({ source, destination }) => {\n    const lists = {\n      DROPPABLE_AREA_TYPE_1: list1,\n      DROPPABLE_AREA_TYPE_2: list2,\n      DROPPABLE_AREA_TYPE_3: list3,\n    };\n    const actions = {\n      DROPPABLE_AREA_TYPE_1: setList1,\n      DROPPABLE_AREA_TYPE_2: setList2,\n      DROPPABLE_AREA_TYPE_3: setList3,\n    };\n    if (source && destination) {\n      if (source.droppableId === destination.droppableId) {\n        const items = reorder(\n          lists[destination.droppableId],\n          source.index,\n          destination.index\n        );\n\n        actions[destination.droppableId](items);\n      } else {\n        const sourceId = source.droppableId;\n        const destinationId = destination.droppableId;\n        const result = move(\n          lists[sourceId],\n          lists[destinationId],\n          source,\n          destination\n        );\n\n        actions[sourceId](result[sourceId]);\n        actions[destinationId](result[destinationId]);\n      }\n    }\n  };\n  return (\n    <EuiDragDropContext onDragEnd={onDragEnd}>\n      <EuiFlexGroup>\n        <EuiFlexItem>\n          <EuiDroppable\n            droppableId=\"DROPPABLE_AREA_TYPE_1\"\n            type=\"TYPE_ONE\"\n            spacing=\"m\"\n            withPanel\n            grow={false}>\n            {list1.map(({ content, id }, idx) => (\n              <EuiDraggable key={id} index={idx} draggableId={id} spacing=\"m\">\n                {(provided, state) => (\n                  <EuiPanel hasShadow={state.isDragging}>\n                    {content}\n                    {state.isDragging && ' ✨'}\n                  </EuiPanel>\n                )}\n              </EuiDraggable>\n            ))}\n          </EuiDroppable>\n        </EuiFlexItem>\n        <EuiFlexItem>\n          <EuiDroppable\n            droppableId=\"DROPPABLE_AREA_TYPE_2\"\n            type=\"TYPE_ONE\"\n            spacing=\"m\"\n            withPanel\n            grow={false}>\n            {list2.map(({ content, id }, idx) => (\n              <EuiDraggable key={id} index={idx} draggableId={id} spacing=\"m\">\n                {(provided, state) => (\n                  <EuiPanel hasShadow={state.isDragging}>\n                    {content}\n                    {state.isDragging && ' ✨'}\n                  </EuiPanel>\n                )}\n              </EuiDraggable>\n            ))}\n          </EuiDroppable>\n        </EuiFlexItem>\n        <EuiFlexItem>\n          <EuiDroppable\n            droppableId=\"DROPPABLE_AREA_TYPE_3\"\n            type=\"TYPE_TWO\"\n            spacing=\"m\"\n            withPanel\n            grow={true}>\n            {list3.map(({ content, id }, idx) => (\n              <EuiDraggable key={id} index={idx} draggableId={id} spacing=\"m\">\n                {(provided, state) => (\n                  <EuiPanel hasShadow={state.isDragging}>\n                    {content}\n                    {state.isDragging && ' ✨'}\n                  </EuiPanel>\n                )}\n              </EuiDraggable>\n            ))}\n          </EuiDroppable>\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    </EuiDragDropContext>\n  );\n};\n"